step.template:
header_rows: list[int] = []
for row_idx, row in enumerate(ws.iter_rows(values_only=False), start=1):
    matches = sum(
        1 for cell in row
        if cell.value and str(cell.value).strip().lower() in KNOWN_HEADERS
    )
    if matches >= 2:
        header_rows.append(row_idx)

# Example: total column as SUM formula
for row in range(2, end_row - header_row_idx + 2):
    ws_out[f"E{row}"] = f"=SUM(B{row}:D{row})"

for row_idx, row in enumerate(ws.iter_rows(min_row=2), start=2):
    fill = even_fill if row_idx % 2 == 0 else odd_fill
    for cell in row:
        cell.fill = fill
        cell.border = data_border
